-- 实验的初始数据库 WisdomCampus（教材"综合实训"附带的库）：环境数据表 EnvironmentData、报警图片表 SecurityData、用户表 Users。
-- EnvironmentData 预置了 7 天的历史数据，"数据分析"的图表一打开就有内容；SecurityData 是空的，拍照或有人入侵时才有记录。
-- 学生可以在数据库页面"恢复实验初始数据"；评分时每个检查项用一份新的。
CREATE DATABASE WisdomCampus
GO
USE WisdomCampus
GO
CREATE TABLE Users (Id int IDENTITY(1,1) PRIMARY KEY, UserName nvarchar(50) NOT NULL, Password nvarchar(50) NOT NULL)
CREATE TABLE EnvironmentData (Id int IDENTITY(1,1) PRIMARY KEY, Fire bit NOT NULL, Smoke bit NOT NULL, Temperature float NULL, Humidity float NULL, Light float NULL, _Time datetime NOT NULL)
CREATE TABLE SecurityData (Id int IDENTITY(1,1) PRIMARY KEY, EvenTime datetime NOT NULL, EvenImage image NOT NULL)
GO
